#!/usr/bin/env python3
"""Measure Rust loose vs packfile stores using identical generated bytes."""
import argparse
import hashlib
import json
import os
from pathlib import Path
import platform
import random
import statistics
import subprocess
import tempfile
import time


def tree_hash(root):
    digest = hashlib.sha256()
    for path in sorted(root.rglob("*")):
        if path.is_file():
            digest.update(path.relative_to(root).as_posix().encode())
            digest.update(path.stat().st_size.to_bytes(8, "little"))
            with path.open("rb") as stream:
                while block := stream.read(1 << 20):
                    digest.update(block)
    return digest.hexdigest()


def generate(root, size_mib, small_files):
    root.mkdir()
    rng = random.Random(404)
    with (root / "large-mixed.dat").open("wb") as stream:
        for block in range(size_mib * 4):
            if block % 3 == 0:
                stream.write(rng.randbytes(256 << 10))
            else:
                seed = hashlib.sha256(f"experiment04-{block}".encode()).digest()
                stream.write(seed * (8192))
    (root / "small").mkdir()
    for i in range(small_files):
        seed = hashlib.sha256(f"small-{i}".encode()).digest()
        (root / "small" / f"asset-{i:05}.dat").write_bytes(seed * 128)
    (root / "duplicate.dat").write_bytes((root / "small" / "asset-00000.dat").read_bytes() if small_files else b"duplicate" * 4096)


def allocation(root):
    files = list(root.rglob("*"))
    stats = {"files": 0, "directories": 1, "encoded_file_bytes": 0, "allocated_file_bytes": 0, "directory_metadata_allocated_bytes": getattr(root.stat(), "st_blocks", 0) * 512}
    for path in files:
        stat = path.stat()
        if path.is_file():
            stats["files"] += 1
            stats["encoded_file_bytes"] += stat.st_size
            stats["allocated_file_bytes"] += getattr(stat, "st_blocks", 0) * 512
        elif path.is_dir():
            stats["directories"] += 1
            stats["directory_metadata_allocated_bytes"] += getattr(stat, "st_blocks", 0) * 512
    stats["allocation_supported"] = hasattr(root.stat(), "st_blocks")
    return stats


def command_json(command, output, name, commands):
    commands.append([str(v) for v in command])
    start = time.perf_counter()
    result = subprocess.run(command, text=True, capture_output=True, check=False)
    (output / f"{name}.stdout.log").write_text(result.stdout)
    (output / f"{name}.stderr.log").write_text(result.stderr)
    if result.returncode:
        raise RuntimeError(f"{name} failed: {result.stderr}")
    return json.loads(result.stdout), time.perf_counter() - start


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--playsparse", type=Path, default=Path("target/release/playsparse"))
    parser.add_argument("--source", type=Path, help="Optional existing read-only source; generated corpus otherwise")
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--work", type=Path)
    parser.add_argument("--size-mib", type=int, default=64)
    parser.add_argument("--small-files", type=int, default=512)
    parser.add_argument("--repetitions", type=int, default=3)
    parser.add_argument("--iterations", type=int, default=200)
    parser.add_argument("--chunker", choices=["fixed", "cdc"], default="fixed")
    parser.add_argument("--chunk-size", default="256K")
    args = parser.parse_args()
    if args.size_mib < 1 or args.small_files < 0 or args.repetitions < 1:
        parser.error("size/repetitions must be positive and small-files nonnegative")
    binary = args.playsparse.resolve(strict=True)
    output = args.output.resolve()
    if output.exists():
        parser.error("output already exists; previous measurements are preserved")
    output.mkdir(parents=True)
    temporary = tempfile.TemporaryDirectory(prefix="playsparse-experiment04-") if args.work is None else None
    work = Path(temporary.name) if temporary else args.work.resolve()
    if temporary is None:
        if work.exists():
            parser.error("work directory already exists")
        work.mkdir(parents=True)
    source = args.source.resolve(strict=True) if args.source else work / "corpus"
    if args.source is None:
        generate(source, args.size_mib, args.small_files)
    before = tree_hash(source)
    report = {"schema": 1, "experiment": "04-loose-vs-packfiles", "os": platform.platform(), "commit": subprocess.check_output(["git", "rev-parse", "HEAD"], text=True).strip(), "dataset": "existing source" if args.source else "synthetic mixed entropy plus many small assets; no real-game claim", "source": str(source), "source_sha256": before, "chunker": args.chunker, "chunk_size": args.chunk_size, "commands": [], "runs": [], "cache_policy": "OS cache is uncontrolled; direct benchmark cold disables decompressed chunk cache only", "allocation_note": "st_blocks*512 includes file allocation and separate directory allocation; absent on Windows", "status": "FAIL"}
    try:
        for repetition in range(args.repetitions):
            # Alternate ordering to reduce a consistent first-run bias.
            for layout in (["loose", "packs"] if repetition % 2 == 0 else ["packs", "loose"]):
                store = work / f"{layout}-{repetition}"
                name = f"{layout}-{repetition}"
                pack, pack_wall = command_json([str(binary), "pack", str(source), str(store), "--layout", layout, "--chunker", args.chunker, "--chunk-size", args.chunk_size], output, name + "-pack", report["commands"])
                verify, verify_wall = command_json([str(binary), "verify", str(store)], output, name + "-verify", report["commands"])
                benchmark, benchmark_wall = command_json([str(binary), "benchmark", str(source), str(store), "--iterations", str(args.iterations), "--output", str(output / (name + "-benchmark.json"))], output, name + "-benchmark", report["commands"])
                metadata_ms = []
                for _ in range(10):
                    start = time.perf_counter()
                    count = sum(1 for _ in store.rglob("*"))
                    metadata_ms.append((time.perf_counter() - start) * 1000)
                report["runs"].append({"layout": layout, "repetition": repetition, "pack": pack, "verify": verify, "pack_wall_seconds": pack_wall, "verify_wall_seconds": verify_wall, "benchmark_wall_seconds": benchmark_wall, "allocation": allocation(store), "directory_enumeration_ms": metadata_ms, "filesystem_entries": count, "benchmark": benchmark})
        report["source_untouched"] = tree_hash(source) == before
        if not report["source_untouched"]:
            raise RuntimeError("source tree changed")
        report["status"] = "PASS"
        summary = []
        for layout in ["loose", "packs"]:
            runs = [r for r in report["runs"] if r["layout"] == layout]
            median = lambda get: statistics.median(get(r) for r in runs)
            row = {"layout": layout, "pack_seconds_median": median(lambda r: r["pack_wall_seconds"]), "physical_encoded_bytes": median(lambda r: r["allocation"]["encoded_file_bytes"]), "allocated_file_bytes": median(lambda r: r["allocation"]["allocated_file_bytes"]), "directory_metadata_allocated_bytes": median(lambda r: r["allocation"]["directory_metadata_allocated_bytes"]), "filesystem_files": median(lambda r: r["allocation"]["files"]), "object_lookup_p95_ms": median(lambda r: r["benchmark"]["object_lookup"]["p95_ms"]), "random_chunk_read_p95_ms": median(lambda r: r["benchmark"]["random_chunk_read"]["p95_ms"]), "sequential_mib_s": median(lambda r: r["benchmark"]["sequential"]["playsparse_mib_s"]), "directory_enumeration_ms_median": median(lambda r: statistics.median(r["directory_enumeration_ms"]))}
            summary.append(row)
        report["summary"] = summary
    except Exception as error:
        report["error"] = str(error)
    finally:
        (output / "result.json").write_text(json.dumps(report, indent=2))
        print(json.dumps({"status": report["status"], "output": str(output), "summary": report.get("summary"), "error": report.get("error")}, indent=2))
        if temporary:
            temporary.cleanup()
    return 0 if report["status"] == "PASS" else 1


if __name__ == "__main__":
    raise SystemExit(main())
